function Logo() { return <div className="brand"><span className="brand-mark"><i /><i /><i /></span><span>streamio</span></div>; }
function Avatar({ initials, color = '#8b7dff', small = false }) { return <span className={`avatar ${small ? 'small' : ''}`} style={{ '--avatar': color }}>{initials}</span>; }
function Status({ children }) { return <span className={`status status-${children.toLowerCase().replace(/\s/g, '-')}`}><i />{children}</span>; }
function Button({ children, variant = 'primary', icon, onClick, className = '' }) { return <button className={`button button-${variant} ${className}`} onClick={onClick}>{icon && <Icon name={icon} size={15} />}{children}</button>; }
function Select({ value, onChange, children }) { return <label className="select-wrap"><select value={value} onChange={e => onChange(e.target.value)}>{children}</select><Icon name="down" size={14} /></label>; }

function Sparkline({ values, color = '#8b7dff', fill = true }) {
  const max = Math.max(...values), min = Math.min(...values);
  const points = values.map((v, i) => `${(i / (values.length - 1)) * 100},${80 - ((v - min) / (max - min || 1)) * 58}`).join(' ');
  return <svg className="sparkline" viewBox="0 0 100 80" preserveAspectRatio="none"><defs><linearGradient id={`g-${color.replace('#', '')}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor={color} stopOpacity=".32" /><stop offset="1" stopColor={color} stopOpacity="0" /></linearGradient></defs>{fill && <polygon points={`0,80 ${points} 100,80`} fill={`url(#g-${color.replace('#', '')})`} />}<polyline points={points} fill="none" stroke={color} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" /><circle cx="100" cy={points.split(' ').at(-1).split(',')[1]} r="3" fill={color} /></svg>;
}
function BarChart() { const values = [44, 58, 49, 72, 66, 82, 76, 91, 73, 87, 96, 88]; return <div className="bar-chart">{values.map((value, i) => <div className="bar-col" key={i}><div className="bar" style={{ height: `${value}%`, animationDelay: `${i * .04}s` }} /><span>{['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'][i]}</span></div>)}</div>; }
function Donut({ segments = [{ value: 42, color: '#8b7dff' }, { value: 34, color: '#72e4ff' }, { value: 24, color: '#ffbc78' }] }) { let offset = 0; return <div className="donut-wrap"><svg viewBox="0 0 42 42" className="donut"><circle cx="21" cy="21" r="15.9" fill="none" stroke="rgba(255,255,255,.07)" strokeWidth="5" />{segments.map((s, i) => { const dash = s.value; const el = <circle key={i} cx="21" cy="21" r="15.9" fill="none" stroke={s.color} strokeWidth="5" strokeDasharray={`${dash} ${100 - dash}`} strokeDashoffset={-offset} transform="rotate(-90 21 21)" />; offset += dash; return el; })}</svg><div className="donut-center"><strong>8,429</strong><span>subscribers</span></div></div>; }

function PageHeader({ eyebrow, title, copy, action, onAction }) { return <div className="page-header"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{copy}</p></div>{action && <Button icon={action.icon} onClick={onAction}>{action.label}</Button>}</div>; }
function StatCard({ label, value, change, icon, color = 'violet', spark = [3, 5, 4, 8, 7, 10, 12] }) { return <article className={`stat-card stat-${color}`}><div className="stat-top"><span>{label}</span><span className="stat-icon"><Icon name={icon} size={17} /></span></div><div className="stat-value">{value}</div><div className="stat-bottom"><span className="change-up"><Icon name="trend" size={13} />{change}</span><span>vs last period</span></div><Sparkline values={spark} color={color === 'cyan' ? '#72e4ff' : color === 'amber' ? '#ffbc78' : '#8b7dff'} /></article>; }
function TableShell({ children, empty = false }) { return <div className={`table-shell ${empty ? 'is-empty' : ''}`}><table>{children}</table></div>; }
function Modal({ title, subtitle, children, onClose }) { return <div className="modal-backdrop" onMouseDown={e => e.target === e.currentTarget && onClose()}><div className="modal"><div className="modal-head"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="close-button" onClick={onClose}><Icon name="close" size={18} /></button></div>{children}</div></div>; }
function Field({ label, children }) { return <label className="field"><span>{label}</span>{children || <input />}</label>; }

function Dashboard({ setPage, showToast }) {
  const content = contentSeed.slice(0, 4);
  return <div className="management-dashboard"><header className="cinema-header management-header"><a className="cinema-logo" href="#management-top"><span className="logo-mark"><i /><i /><i /></span><span>streamio</span></a><span className="ops-label">OPERATIONS CONSOLE</span><div className="cinema-admin-nav" aria-label="Admin pages">{nav.map(item => <button key={item.key} className={item.key === 'dashboard' ? 'active' : ''} onClick={() => item.key === 'dashboard' ? setPage('dashboard') : setPage(item.key)}>{item.label}</button>)}</div><div className="cinema-actions"><label><Icon name="search" size={16} /><input placeholder="Search operations" onChange={() => {}} /></label><button onClick={() => showToast('You have 3 new operational alerts')}><Icon name="bell" size={18} /></button><span className="cinema-avatar">A</span></div></header><main id="management-top" className="management-main"><section className="management-hero"><div className="management-hero-copy"><span className="cinema-eyebrow"><span><i /> Platform command</span><b>SYS / 026</b></span><h1>Command the<br /><em>signal.</em></h1><p>One view of the audience, catalog, revenue, and playback systems powering your streaming service.</p><div className="management-meta"><span className="health-pill"><i /> All systems nominal</span><span>Last sync · 11:48 PM</span><span>Region · Global</span></div></div><div className="management-hero-graphic"><div className="management-grid-lines" /><div className="management-orbit management-orbit-a" /><div className="management-orbit management-orbit-b" /><div className="management-core"><span>LIVE</span><strong>96.8</strong><small>PLATFORM HEALTH</small></div><div className="management-readout readout-a"><b>1.84M</b><span>sessions processed</span></div><div className="management-readout readout-b"><b>18,430</b><span>active viewers</span></div><span className="graphic-code">STO / OPS<br />STREAMIO CONTROL</span><div className="management-beam beam-a" /><div className="management-beam beam-b" /><div className="management-scan" /><div className="telemetry-dot telemetry-dot-a" /><div className="telemetry-dot telemetry-dot-b" /><div className="telemetry-dot telemetry-dot-c" /><span className="telemetry-label telemetry-label-a">EDGE / 42 REGIONS</span><span className="telemetry-label telemetry-label-b">LATENCY 42ms</span></div></section><section className="stats-grid management-stats"><StatCard label="Active viewers" value="18,430" change="8.4%" icon="users" color="cyan" spark={[4,6,5,8,9,12,15]} /><StatCard label="Watch time today" value="84,291h" change="12.4%" icon="history" spark={[4,5,8,7,11,12,16]} /><StatCard label="Monthly revenue" value="$284.9k" change="18.2%" icon="wallet" color="amber" spark={[3,5,4,8,10,13,15]} /><StatCard label="Content health" value="96.8%" change="2.6%" icon="check" spark={[7,7,8,9,10,10,12]} /></section><div className="dashboard-grid management-grid"><section className="panel management-chart-panel"><div className="panel-head"><div><span className="eyebrow">Audience intelligence</span><h2>Platform engagement <em>+12.4% vs last period</em></h2></div><div className="chart-note"><i /> Live telemetry</div></div><BarChart /></section><section className="panel platform-pulse"><div className="panel-head"><div><span className="eyebrow">System pulse</span><h2>Operating health</h2></div><Status>Active</Status></div><div className="pulse-ring"><div><strong>96.8%</strong><span>nominal</span></div></div><div className="pulse-list"><span><b>Playback delivery</b><i><em style={{ width: '98%' }} /></i><small>98%</small></span><span><b>Catalog indexing</b><i><em style={{ width: '94%' }} /></i><small>94%</small></span><span><b>Payments gateway</b><i><em style={{ width: '99%' }} /></i><small>99%</small></span></div></section></div><div className="dashboard-grid management-grid lower-grid"><section className="panel operations-panel"><div className="panel-head"><div><span className="eyebrow">Catalog intelligence</span><h2>Top performing content</h2></div><button className="text-action" onClick={() => setPage('content')}>Open catalog <Icon name="arrow" size={14} /></button></div><div className="operations-content-list">{content.map((item, i) => <div className="operations-content-row" key={item.title}><span className="ops-rank">0{i + 1}</span><img src={item.image} alt="" /><div><strong>{item.title}</strong><span>{item.type} · {item.genre}</span></div><div className="ops-bar"><i style={{ width: `${[92,87,81,74][i]}%` }} /></div><b>{[92,87,81,74][i]}%</b></div>)}</div></section><section className="panel activity-panel"><div className="panel-head"><div><span className="eyebrow">Operations feed</span><h2>Recent activity</h2></div><button className="icon-button" onClick={() => showToast('Activity feed refreshed')}><Icon name="more" /></button></div><div className="activity-feed"><div><span className="feed-icon cyan"><Icon name="play" size={14} /></span><p><b>Playback peak detected</b><span>18.4k concurrent viewers · 2m ago</span></p></div><div><span className="feed-icon violet"><Icon name="upload" size={14} /></span><p><b>New title published</b><span>Signal / 07 is live in 42 regions · 18m ago</span></p></div><div><span className="feed-icon amber"><Icon name="wallet" size={14} /></span><p><b>Revenue milestone reached</b><span>Monthly run-rate crossed $284k · 41m ago</span></p></div><div><span className="feed-icon green"><Icon name="users" size={14} /></span><p><b>Audience segment updated</b><span>18,430 active viewers indexed · 1h ago</span></p></div></div></section></div></main></div>;
}
function Users({ showToast, openModal, setModal, users, setUsers }) {
  const [query, setQuery] = useState(''); const [plan, setPlan] = useState('All plans'); const [status, setStatus] = useState('All status'); const [page, setPage] = useState(1);
  const filtered = users.filter(u => `${u.name} ${u.email} ${u.id}`.toLowerCase().includes(query.toLowerCase()) && (plan === 'All plans' || u.plan === plan) && (status === 'All status' || u.status === status));
  const edit = user => setModal({ type: 'user', user });
  return <div className="page-enter pdf-page users-page"><PageHeader eyebrow="Audience / Directory" title="Users" copy="Manage your members, plans, and account health." action={{ label: 'Add user', icon: 'plus' }} onAction={() => setModal({ type: 'user', user: null })} /><div className="toolbar-row table-toolbar"><label className="search-field"><Icon name="search" size={16} /><input value={query} onChange={e => { setQuery(e.target.value); setPage(1); }} placeholder="Search users, emails, or IDs" /></label><Select value={plan} onChange={setPlan}><option>All plans</option><option>Premium</option><option>Standard</option><option>Basic</option></Select><Select value={status} onChange={setStatus}><option>All status</option><option>Active</option><option>Inactive</option></Select><Button variant="ghost" icon="download" onClick={() => showToast('Users CSV exported')}>Export</Button></div><section className="panel table-panel"><div className="panel-head"><div><span className="eyebrow">{filtered.length} members</span><h2>Member directory</h2></div><span className="table-meta">Updated just now</span></div><TableShell><thead><tr><th>User</th><th>Plan</th><th>Status</th><th>Joined</th><th>Last active</th><th>Watch time</th><th /></tr></thead><tbody>{filtered.map(user => <tr key={user.id}><td><div className="user-cell"><Avatar initials={user.initials} color={user.color} small /><div><strong>{user.name}</strong><span>{user.email}</span></div></div></td><td><span className={`plan-pill plan-${user.plan.toLowerCase()}`}>{user.plan}</span></td><td><Status>{user.status}</Status></td><td>{user.join}</td><td>{user.active}</td><td>{user.watch}</td><td><button className="row-action" onClick={() => edit(user)}><Icon name="more" /></button></td></tr>)}</tbody></TableShell><div className="pagination"><span>Showing {filtered.length ? (page - 1) * 5 + 1 : 0}-{Math.min(page * 5, filtered.length)} of {filtered.length}</span><div><button disabled={page === 1} onClick={() => setPage(page - 1)}>Previous</button><button className="current">{page}</button><button disabled={page * 5 >= filtered.length} onClick={() => setPage(page + 1)}>Next</button></div></div></section>{openModal?.type === 'user' && <UserModal data={openModal.user} onClose={() => setModal(null)} onSave={user => { setUsers(current => user.id ? current.map(u => u.id === user.id ? { ...u, ...user } : u) : [{ ...user, id: `USR-${1043 + current.length}`, initials: user.name.split(' ').map(x => x[0]).join('').slice(0, 2), color: '#9d8cff', join: 'Oct 02, 2026', active: 'Just now', watch: '0h 00m' }, ...current]); setModal(null); showToast(user.id ? 'User profile updated' : 'User invited successfully'); }} onDelete={user => { setUsers(current => current.filter(u => u.id !== user.id)); setModal(null); showToast('User deactivated'); }} />}</div>;
}
function UserModal({ data, onClose, onSave, onDelete }) { const [form, setForm] = useState(data || { name: '', email: '', plan: 'Standard', status: 'Active' }); const update = (key, value) => setForm({ ...form, [key]: value }); return <Modal title={data ? 'Edit user' : 'Add user'} subtitle={data ? `Managing ${data.id}` : 'Invite a new member to Streamio'} onClose={onClose}><div className="modal-form"><Field label="Full name"><input value={form.name} onChange={e => update('name', e.target.value)} /></Field><Field label="Email address"><input value={form.email} onChange={e => update('email', e.target.value)} /></Field><Field label="Subscription plan"><Select value={form.plan} onChange={v => update('plan', v)}><option>Basic</option><option>Standard</option><option>Premium</option></Select></Field><Field label="Account status"><Select value={form.status} onChange={v => update('status', v)}><option>Active</option><option>Inactive</option></Select></Field><div className="modal-actions"><Button variant="ghost" onClick={onClose}>Cancel</Button>{data && <Button variant="danger" icon="trash" onClick={() => onDelete(data)}>Deactivate</Button>}<Button onClick={() => onSave(form)}>Save changes</Button></div></div></Modal>; }

function Content({ showToast, openModal, setModal, content, setContent }) { const [query, setQuery] = useState(''); const [genre, setGenre] = useState('All genres'); const [type, setType] = useState('All types'); const [status, setStatus] = useState('All status'); const filtered = content.filter(item => `${item.title} ${item.genre}`.toLowerCase().includes(query.toLowerCase()) && (genre === 'All genres' || item.genre === genre) && (type === 'All types' || item.type === type) && (status === 'All status' || item.status === status)); return <div className="page-enter pdf-page content-page"><PageHeader eyebrow="Library / Catalog" title="Content" copy="Keep your catalog fresh, discoverable, and beautifully presented." action={{ label: 'Add content', icon: 'plus' }} onAction={() => setModal({ type: 'content', item: null })} /><div className="toolbar-row table-toolbar"><label className="search-field"><Icon name="search" size={16} /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search titles or genres" /></label><Select value={genre} onChange={setGenre}><option>All genres</option><option>Drama</option><option>Sci-fi</option><option>Thriller</option><option>Mystery</option><option>Comedy</option></Select><Select value={type} onChange={setType}><option>All types</option><option>Movie</option><option>Series</option></Select><Select value={status} onChange={setStatus}><option>All status</option><option>Published</option><option>Draft</option></Select></div><div className="content-grid">{filtered.map(item => <article className="content-admin-card" key={item.id}><div className="content-poster"><img src={item.image} alt={`${item.title} poster`} /><div className="poster-actions"><button onClick={() => setModal({ type: 'content-detail', item })}><Icon name="play" size={14} /> Preview</button><button onClick={() => setModal({ type: 'content', item })}><Icon name="edit" size={14} /></button></div></div><div className="content-card-body"><div><span className="eyebrow">{item.type} · {item.year}</span><h3>{item.title}</h3></div><Status>{item.status}</Status><div className="content-meta"><span>{item.genre}</span><span>{item.duration}</span><span>{item.views} views</span><b>★ {item.rating}</b></div></div></article>)}</div>{openModal?.type === 'content' && <ContentModal data={openModal.item} onClose={() => setModal(null)} onSave={item => { setContent(current => item.id ? current.map(x => x.id === item.id ? { ...x, ...item } : x) : [{ ...item, id: `CNT-${83 + current.length}`, views: '0', rating: '—', date: 'Oct 02, 2026', image: art.signal }, ...current]); setModal(null); showToast(item.id ? 'Content updated' : 'Content added to catalog'); }} />}{openModal?.type === 'content-detail' && <Modal title={openModal.item.title} subtitle={`${openModal.item.type} · ${openModal.item.genre} · ${openModal.item.year}`} onClose={() => setModal(null)}><div className="detail-preview"><img src={openModal.item.image} alt="" /><div><p>“A premium Streamio original with a strong audience signal.”</p><div className="detail-stats"><span><b>{openModal.item.views}</b> Views</span><span><b>{openModal.item.rating}</b> Rating</span><span><b>{openModal.item.duration}</b> Runtime</span></div><Button onClick={() => setModal(null)}>Close preview</Button></div></div></Modal>}</div>; }
function ContentModal({ data, onClose, onSave }) { const [form, setForm] = useState(data || { title: '', type: 'Movie', genre: 'Drama', year: 2026, duration: '1h 40m', status: 'Draft' }); const update = (k, v) => setForm({ ...form, [k]: v }); return <Modal title={data ? 'Edit content' : 'Add content'} subtitle="Manage title metadata and availability" onClose={onClose}><div className="modal-form"><Field label="Title"><input value={form.title} onChange={e => update('title', e.target.value)} /></Field><div className="form-row"><Field label="Type"><Select value={form.type} onChange={v => update('type', v)}><option>Movie</option><option>Series</option></Select></Field><Field label="Genre"><Select value={form.genre} onChange={v => update('genre', v)}><option>Drama</option><option>Sci-fi</option><option>Thriller</option><option>Mystery</option><option>Comedy</option></Select></Field></div><div className="form-row"><Field label="Release year"><input value={form.year} onChange={e => update('year', e.target.value)} /></Field><Field label="Duration"><input value={form.duration} onChange={e => update('duration', e.target.value)} /></Field></div><Field label="Availability"><Select value={form.status} onChange={v => update('status', v)}><option>Draft</option><option>Published</option></Select></Field><div className="modal-actions"><Button variant="ghost" onClick={onClose}>Cancel</Button><Button onClick={() => onSave(form)}>Save content</Button></div></div></Modal>; }

function Subscription({ showToast }) { const [cycle, setCycle] = useState('Monthly'); return <div className="page-enter pdf-page subscription-page"><PageHeader eyebrow="Growth / Monetization" title="Subscription" copy="Understand plan health, recurring revenue, and retention." action={{ label: 'Create plan', icon: 'plus' }} onAction={() => showToast('Plan builder opened')} /><div className="toolbar-row"><div className="segmented"><button className={cycle === 'Monthly' ? 'selected' : ''} onClick={() => setCycle('Monthly')}>Monthly</button><button className={cycle === 'Annual' ? 'selected' : ''} onClick={() => setCycle('Annual')}>Annual</button></div><Select value="This quarter" onChange={() => showToast('Subscription range updated')}><option>This quarter</option><option>Last quarter</option><option>This year</option></Select></div><div className="stats-grid"><StatCard label="Active subscriptions" value="8,429" change="6.7%" icon="card" /><StatCard label="Monthly recurring revenue" value="$112,480" change="14.3%" icon="wallet" color="amber" /><StatCard label="Renewal rate" value="94.8%" change="2.1%" icon="check" color="cyan" /><StatCard label="Monthly churn" value="2.4%" change="0.8%" icon="trend" /></div><div className="dashboard-grid"><section className="panel subscription-chart"><div className="panel-head"><div><span className="eyebrow">Subscription growth</span><h2>New members per month</h2></div><span className="chart-note"><i /> Members</span></div><BarChart /></section><section className="panel"><div className="panel-head"><div><span className="eyebrow">Distribution</span><h2>Plan health</h2></div></div><div className="distribution"><Donut segments={[{ value: 42, color: '#8b7dff' }, { value: 36, color: '#72e4ff' }, { value: 22, color: '#ffbc78' }]} /><div className="legend"><span><i style={{ background: '#8b7dff' }} />Premium <b>3,541</b></span><span><i style={{ background: '#72e4ff' }} />Standard <b>3,034</b></span><span><i style={{ background: '#ffbc78' }} />Basic <b>1,854</b></span></div></div></section></div><section className="panel plans-panel"><div className="panel-head"><div><span className="eyebrow">Offer architecture</span><h2>Subscription plans</h2></div><Button variant="ghost" onClick={() => showToast('Plan comparison copied')}>Compare plans <Icon name="arrow" size={14} /></Button></div><div className="plans-grid">{[['Basic', '$7.99', '1,854', '$14,812', '91.2%', '#ffbc78'], ['Standard', '$12.99', '3,034', '$39,411', '94.7%', '#72e4ff'], ['Premium', '$19.99', '3,541', '$70,740', '97.1%', '#8b7dff']].map((p, i) => <div className={`plan-card ${i === 2 ? 'featured' : ''}`} key={p[0]}><div className="plan-accent" style={{ background: p[5] }} /><span className="eyebrow">{i === 2 ? 'Most valuable' : 'Plan'}</span><h3>{p[0]}</h3><strong>{p[1]}<small>/ month</small></strong><div className="plan-stats"><span><b>{p[2]}</b> subscribers</span><span><b>{p[3]}</b> revenue</span><span><b>{p[4]}</b> renewal rate</span></div><Button variant={i === 2 ? 'primary' : 'ghost'} onClick={() => showToast(`${p[0]} plan editor opened`)}>Manage plan</Button></div>)}</div></section></div>; }

function Payment({ showToast, openModal, setModal }) { const [query, setQuery] = useState(''); const [status, setStatus] = useState('All status'); const filtered = paymentsSeed.filter(p => `${p.id} ${p.user} ${p.plan}`.toLowerCase().includes(query.toLowerCase()) && (status === 'All status' || p.status === status)); return <div className="page-enter pdf-page payment-page"><PageHeader eyebrow="Finance / Transactions" title="Payment" copy="Track revenue, payment health, and customer billing activity." action={{ label: 'Export report', icon: 'download' }} onAction={() => showToast('Payment report downloaded')} /><div className="stats-grid"><StatCard label="Total revenue" value="$284,920" change="18.2%" icon="wallet" color="amber" /><StatCard label="Successful payments" value="12,842" change="9.4%" icon="check" color="cyan" /><StatCard label="Failed payments" value="184" change="1.8%" icon="trend" /><StatCard label="Refunds issued" value="$6,420" change="4.2%" icon="arrow" /></div><section className="panel table-panel"><div className="toolbar-row table-toolbar"><label className="search-field"><Icon name="search" size={16} /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search transactions or users" /></label><Select value={status} onChange={setStatus}><option>All status</option><option>Successful</option><option>Failed</option><option>Refunded</option><option>Pending</option></Select><Select value="All methods" onChange={() => showToast('Payment method filter updated')}><option>All methods</option><option>Card</option><option>Apple Pay</option><option>PayPal</option></Select><Button variant="ghost" icon="download" onClick={() => showToast('Transactions CSV exported')}>Export</Button></div><div className="panel-head"><div><span className="eyebrow">{filtered.length} transactions</span><h2>Recent payments</h2></div></div><TableShell><thead><tr><th>Transaction</th><th>User</th><th>Amount</th><th>Payment method</th><th>Date</th><th>Status</th><th /></tr></thead><tbody>{filtered.map(payment => <tr key={payment.id}><td><strong className="mono">{payment.id}</strong><span className="table-sub">{payment.plan}</span></td><td>{payment.user}</td><td><strong>{payment.amount}</strong></td><td>{payment.method}</td><td>{payment.date}</td><td><Status>{payment.status}</Status></td><td><button className="row-action" onClick={() => setModal({ type: 'payment', payment })}><Icon name="more" /></button></td></tr>)}</tbody></TableShell></section>{openModal?.type === 'payment' && <Modal title="Transaction details" subtitle={openModal.payment.id} onClose={() => setModal(null)}><div className="transaction-detail"><div className="transaction-amount">{openModal.payment.amount}<Status>{openModal.payment.status}</Status></div><div className="detail-list"><span><b>Customer</b>{openModal.payment.user}</span><span><b>Subscription</b>{openModal.payment.plan}</span><span><b>Payment method</b>{openModal.payment.method}</span><span><b>Processed</b>{openModal.payment.date}</span></div><div className="modal-actions"><Button variant="ghost" onClick={() => setModal(null)}>Close</Button>{openModal.payment.status === 'Successful' && <Button variant="danger" onClick={() => { setModal(null); showToast('Refund request created'); }}>Issue refund</Button>}</div></div></Modal>}</div>; }

function History({ showToast }) { const [query, setQuery] = useState(''); const [device, setDevice] = useState('All devices'); const [page, setPage] = useState(1); const filtered = historySeed.filter(h => `${h.user} ${h.content}`.toLowerCase().includes(query.toLowerCase()) && (device === 'All devices' || h.device.includes(device))); return <div className="page-enter pdf-page history-page"><PageHeader eyebrow="Audience / Engagement" title="Watch History" copy="See what your audience is watching, finishing, and returning to." action={{ label: 'Export history', icon: 'download' }} onAction={() => showToast('Watch history exported')} /><div className="stats-grid"><StatCard label="Total watch time" value="84,291h" change="12.4%" icon="history" /><StatCard label="Active viewers" value="18,430" change="8.4%" icon="users" color="cyan" /><StatCard label="Avg. watch duration" value="48m 12s" change="5.8%" icon="play" color="amber" /><StatCard label="Completion rate" value="76.8%" change="3.2%" icon="check" /></div><div className="dashboard-grid"><section className="panel history-trend"><div className="panel-head"><div><span className="eyebrow">Viewing trends</span><h2>Minutes watched</h2></div><Select value="Last 7 days" onChange={() => showToast('Viewing range updated')}><option>Last 7 days</option><option>Last 30 days</option></Select></div><Sparkline values={[34, 46, 42, 58, 52, 69, 81, 78, 91]} color="#72e4ff" /></section><section className="panel device-panel"><div className="panel-head"><div><span className="eyebrow">Playback mix</span><h2>Devices</h2></div></div><div className="device-bars"><span><b>TV</b><i style={{ width: '68%' }} /><small>68%</small></span><span><b>Web</b><i style={{ width: '21%' }} /><small>21%</small></span><span><b>Mobile</b><i style={{ width: '11%' }} /><small>11%</small></span></div></section></div><section className="panel table-panel"><div className="toolbar-row table-toolbar"><label className="search-field"><Icon name="search" size={16} /><input value={query} onChange={e => { setQuery(e.target.value); setPage(1); }} placeholder="Search viewers or content" /></label><Select value={device} onChange={setDevice}><option>All devices</option><option>TV</option><option>Web</option><option>Mobile</option><option>Tablet</option></Select><Select value="All dates" onChange={() => showToast('Watch date filter updated')}><option>All dates</option><option>Today</option><option>This week</option></Select></div><div className="panel-head"><div><span className="eyebrow">{filtered.length} viewing sessions</span><h2>Detailed watch history</h2></div></div><TableShell><thead><tr><th>Viewer</th><th>Content</th><th>Watched date</th><th>Duration</th><th>Completion</th><th>Device</th><th>Status</th></tr></thead><tbody>{filtered.map(row => <tr key={row.id}><td><div className="user-cell"><Avatar initials={row.user.split(' ').map(x => x[0]).join('')} small /><strong>{row.user}</strong></div></td><td><div className="history-content"><img src={row.image} alt="" /><strong>{row.content}</strong></div></td><td>{row.date}</td><td>{row.duration}</td><td><div className="completion"><i style={{ width: `${row.complete}%` }} /><span>{row.complete}%</span></div></td><td>{row.device}</td><td><Status>{row.status}</Status></td></tr>)}</tbody></TableShell><div className="pagination"><span>Showing 1-{filtered.length} of {filtered.length}</span><div><button disabled={page === 1} onClick={() => setPage(page - 1)}>Previous</button><button className="current">{page}</button><button disabled>Next</button></div></div></section></div>; }

function Reviews({ showToast }) {
  const [query, setQuery] = useState('');
  const [sentiment, setSentiment] = useState('All sentiment');
  const [rating, setRating] = useState('All ratings');
  const [selected, setSelected] = useState(null);
  const filtered = reviewsSeed.filter(review => `${review.user} ${review.content} ${review.text}`.toLowerCase().includes(query.toLowerCase()) && (sentiment === 'All sentiment' || review.sentiment === sentiment) && (rating === 'All ratings' || String(review.rating) === rating));
  return <div className="page-enter pdf-page reviews-page"><PageHeader eyebrow="Audience / Voice" title="Reviews" copy="Keep a pulse on what your audience feels after the credits roll." action={{ label: 'Export reviews', icon: 'download' }} onAction={() => showToast('Reviews CSV exported')} /><div className="stats-grid"><StatCard label="Average rating" value="4.6 / 5" change="0.3" icon="star" color="amber" spark={[4,5,5,6,7,8,9]} /><StatCard label="Reviews this month" value="1,284" change="18.4%" icon="trend" color="cyan" spark={[3,5,4,8,9,12,16]} /><StatCard label="Positive sentiment" value="82.4%" change="4.8%" icon="check" spark={[6,6,8,7,10,11,14]} /><StatCard label="Response rate" value="68.9%" change="7.2%" icon="users" spark={[4,6,5,7,9,10,13]} /></div><div className="dashboard-grid reviews-top"><section className="panel sentiment-panel"><div className="panel-head"><div><span className="eyebrow">Audience sentiment</span><h2>How viewers feel</h2></div><button className="icon-button" onClick={() => showToast('Sentiment report refreshed')}><Icon name="more" /></button></div><div className="sentiment-score"><div className="score-ring"><span>4.6</span><small>out of 5</small></div><div className="rating-bars">{[5,4,3,2,1].map((star, i) => <div className="rating-row" key={star}><span>{star} <Icon name="star" size={11} /></span><i><b style={{ width: `${[74,18,5,2,1][i]}%` }} /></i><small>{[74,18,5,2,1][i]}%</small></div>)}</div></div></section><section className="panel"><div className="panel-head"><div><span className="eyebrow">Content resonance</span><h2>Top reviewed titles</h2></div><Button variant="ghost" onClick={() => showToast('Review trends opened')}>View trends <Icon name="arrow" size={14} /></Button></div><div className="review-titles">{[['Signal / 07','4.9','284'],['Velvet Static','4.7','221'],['Afterglow','4.5','176']].map((item, i) => <div className="review-title-row" key={item[0]}><span className="rank">0{i+1}</span><div className="review-title-art" style={{ backgroundImage: `url(${[art.signal, art.velvet, art.afterglow][i]})` }} /><div><strong>{item[0]}</strong><span><Icon name="star" size={11} /> {item[1]} · {item[2]} reviews</span></div><Icon name="chevron" size={15} /></div>)}</div></section></div><section className="panel review-table-panel"><div className="toolbar-row table-toolbar"><label className="search-field"><Icon name="search" size={16} /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search reviews, users, or titles" /></label><Select value={sentiment} onChange={setSentiment}><option>All sentiment</option><option>Positive</option><option>Neutral</option><option>Negative</option></Select><Select value={rating} onChange={setRating}><option>All ratings</option><option value="5">5 stars</option><option value="4">4 stars</option><option value="3">3 stars</option><option value="2">2 stars</option></Select></div><div className="panel-head"><div><span className="eyebrow">{filtered.length} published reviews</span><h2>Latest audience feedback</h2></div><span className="table-meta">Auto-moderation on</span></div><TableShell><thead><tr><th>Reviewer</th><th>Content</th><th>Rating</th><th>Review</th><th>Sentiment</th><th>Date</th><th /></tr></thead><tbody>{filtered.map(review => <tr key={review.id}><td><div className="user-cell"><Avatar initials={review.initials} color={review.color} small /><strong>{review.user}</strong></div></td><td>{review.content}</td><td><span className="star-rating">{'★'.repeat(review.rating)}<i>{'★'.repeat(5 - review.rating)}</i></span></td><td className="review-copy">{review.text}</td><td><Status>{review.sentiment}</Status></td><td>{review.date}</td><td><button className="row-action" onClick={() => setSelected(review)}><Icon name="more" /></button></td></tr>)}</tbody></TableShell></section>{selected && <Modal title={`${selected.content} review`} subtitle={`${selected.id} · ${selected.date}`} onClose={() => setSelected(null)}><div className="review-detail"><div className="review-detail-head"><Avatar initials={selected.initials} color={selected.color} /><div><strong>{selected.user}</strong><span>{selected.sentiment} sentiment</span></div><span className="star-rating">{'★'.repeat(selected.rating)}<i>{'★'.repeat(5 - selected.rating)}</i></span></div><blockquote>“{selected.text}”</blockquote><div className="modal-actions"><Button variant="ghost" onClick={() => setSelected(null)}>Close</Button><Button onClick={() => { setSelected(null); showToast(`Reply composer opened for ${selected.user}`); }}>Reply to review</Button></div></div></Modal>}</div>;
}

function App() {
  const [page, setPage] = useState('dashboard'); const [mobileOpen, setMobileOpen] = useState(false); const [modal, setModal] = useState(null); const [toast, setToast] = useState(''); const [users, setUsers] = useState(usersSeed); const [content, setContent] = useState(contentSeed);
  useEffect(() => { if (!toast) return; const t = setTimeout(() => setToast(''), 2600); return () => clearTimeout(t); }, [toast]);
  const showToast = text => setToast(text);
  const pages = { dashboard: <Dashboard setPage={setPage} showToast={showToast} />, users: <Users showToast={showToast} openModal={modal} setModal={setModal} users={users} setUsers={setUsers} />, content: <Content showToast={showToast} openModal={modal} setModal={setModal} content={content} setContent={setContent} />, subscription: <Subscription showToast={showToast} />, payment: <Payment showToast={showToast} openModal={modal} setModal={setModal} />, history: <History showToast={showToast} />, reviews: <Reviews showToast={showToast} /> };
  return <div className={`admin-shell ${page === 'dashboard' ? 'cinematic-mode' : ''}`}><div className={`sidebar-backdrop ${mobileOpen ? 'show' : ''}`} onClick={() => setMobileOpen(false)} /><aside className={`sidebar ${mobileOpen ? 'mobile-open' : ''}`}><div className="sidebar-top"><Logo /><button className="mobile-close" onClick={() => setMobileOpen(false)}><Icon name="close" size={18} /></button></div><div className="workspace-switch"><span className="workspace-avatar">S</span><div><strong>Streamio</strong><small>Admin workspace</small></div><Icon name="down" size={14} /></div><nav className="sidebar-nav">{nav.map(item => <button key={item.key} className={page === item.key ? 'active' : ''} onClick={() => { setPage(item.key); setMobileOpen(false); }}><Icon name={item.icon} size={18} /><span>{item.label}</span>{item.key === 'users' && <b>24.9k</b>}</button>)}</nav><div className="sidebar-bottom"><button onClick={() => showToast('Settings panel opened')}><Icon name="settings" size={18} /><span>Settings</span></button><div className="upgrade-card"><span className="eyebrow">Signal pro</span><strong>Unlock deeper<br />audience insights.</strong><button onClick={() => showToast('Upgrade flow opened')}>Explore plan <Icon name="arrow" size={13} /></button></div><div className="admin-profile"><Avatar initials="AR" color="#8b7dff" small /><div><strong>Alex Rivera</strong><span>Administrator</span></div><button onClick={() => showToast('Profile menu opened')}><Icon name="more" size={16} /></button></div></div></aside><div className="main-area"><header className="topbar"><button className="mobile-menu" onClick={() => setMobileOpen(true)}><span /><span /></button><div className="topbar-context"><span>Workspace</span><Icon name="chevron" size={14} /><strong>{nav.find(n => n.key === page)?.label}</strong></div><div className="topbar-actions"><label className="global-search"><Icon name="search" size={16} /><input placeholder="Search anything" onChange={e => e.target.value && showToast(`Searching for “${e.target.value}”`)} /></label><button className="topbar-icon" onClick={() => showToast('You have 3 new notifications')}><Icon name="bell" size={18} /><i /></button><div className="topbar-avatar">AR</div></div></header><main className="content-area">{pages[page]}</main></div>{toast && <div className="toast" role="status"><span className="toast-check"><Icon name="check" size={14} /></span>{toast}</div>}</div>;
}

function DatabaseApp() {
  const [page, setPage] = useState('dashboard');
  const [mobileOpen, setMobileOpen] = useState(false);
  const [toast, setToast] = useState('');
  useEffect(() => {
    if (!toast) return undefined;
    const timer = setTimeout(() => setToast(''), 3200);
    return () => clearTimeout(timer);
  }, [toast]);
  const showToast = text => setToast(text);

  return <div className={`admin-shell ${page === 'dashboard' ? 'cinematic-mode' : ''}`}>
    <div className={`sidebar-backdrop ${mobileOpen ? 'show' : ''}`} onClick={() => setMobileOpen(false)} />
    <aside className={`sidebar ${mobileOpen ? 'mobile-open' : ''}`}>
      <div className="sidebar-top"><Logo /><button className="mobile-close" onClick={() => setMobileOpen(false)}><Icon name="close" size={18} /></button></div>
      <div className="workspace-switch"><span className="workspace-avatar">S</span><div><strong>Streamio</strong><small>Admin workspace</small></div><Icon name="down" size={14} /></div>
      <nav className="sidebar-nav">{nav.map(item => <button key={item.key} className={page === item.key ? 'active' : ''} onClick={() => { setPage(item.key); setMobileOpen(false); }}><Icon name={item.icon} size={18} /><span>{item.label}</span></button>)}</nav>
      <div className="sidebar-bottom"><div className="upgrade-card"><span className="eyebrow">Data source</span><strong>MySQL<br />streaming_platform_db</strong><span className="service-label">FastAPI · live records</span></div><div className="admin-profile"><Avatar initials="DB" color="#72e4ff" small /><div><strong>Streamio</strong><span>Management console</span></div></div></div>
    </aside>
    <div className="main-area">
      <header className="topbar"><button className="mobile-menu" onClick={() => setMobileOpen(true)}><span /><span /></button><div className="topbar-context"><span>Workspace</span><Icon name="chevron" size={14} /><strong>{nav.find(item => item.key === page)?.label}</strong></div><div className="topbar-actions"><span className="service-label">API · localhost:8000</span></div></header>
      <main className="content-area"><DatabaseConsole pageKey={page} setPage={setPage} showToast={showToast} /></main>
    </div>
    {toast && <div className="toast"><Icon name="check" size={16} />{toast}</div>}
  </div>;
}

createRoot(document.getElementById('root')).render(<DatabaseApp />);
